      type: "button",
      title,
      icon,
      visible,
      disabled,
      tooltip: resolve<React.ReactChild>(action.tooltip, context),
      selected: resolve<boolean>(action.selected, context),
      dangerous: action.dangerous,
      shortcut: action.shortcut,
      onClick: () => performAction(action, context),
